/**
 * Renders the rule tables in docs/verification.md from rules.ts, between
 * the `verify:rules` markers. `pnpm verify docs` rewrites them; the
 * `rules-drift` check fails if the committed copy is stale.
 */
import { CHECKS, CLASSES, E2E_MAP, EVIDENCE, OBLIGATIONS, UNCLASSIFIED } from "./rules.ts";

export const START =
  "<!-- verify:rules:start (generated by `pnpm verify docs`; edit scripts/verify/rules.ts) -->";
export const END = "<!-- verify:rules:end -->";

const code = (s: string) => `\`${s.replaceAll("|", "\\|")}\``;
const list = (xs: readonly string[]) => (xs.length ? xs.join(", ") : "—");
const glob = (g: string) => code(g.replaceAll("[[]", "[").replaceAll("[]]", "]"));

const e2eLabel = { none: "—", mapped: "mapped specs", all: "whole suite", self: "changed specs" };

export function renderRules(): string {
  const out: string[] = [];
  out.push("### Change classes", "");
  out.push("First match wins, top to bottom. `full` means every check below.", "");
  out.push("| Side | Class | Paths | Checks | E2E | Obligations | Manual evidence |");
  out.push("| --- | --- | --- | --- | --- | --- | --- |");
  for (const c of [...CLASSES, UNCLASSIFIED]) {
    const paths = c.paths.length ? c.paths.map(glob).join(", ") : "anything else";
    const checks = c.checks === "full" ? "**full**" : c.checks.map(code).join(", ");
    out.push(
      `| ${c.side} | **${c.id}**: ${c.title} | ${paths} | ${checks} | ${e2eLabel[c.e2e]} | ${list(
        (c.obligations ?? []).map(code),
      )} | ${list((c.evidence ?? []).map(code))} |`,
    );
  }
  out.push("", "### Checks", "");
  out.push("Run in this order. Drift checks regenerate a committed file and fail if it changed.");
  out.push("", "| Check | What | Command | Needs |", "| --- | --- | --- | --- |");
  for (const c of CHECKS) {
    const what = c.drift ? `${c.title} (drift: ${c.drift.map(code).join(", ")})` : c.title;
    out.push(`| ${code(c.id)} | ${what} | ${code(c.command)} | ${list(c.needs ?? [])} |`);
  }
  out.push("", "### Obligations", "");
  out.push(
    "A class with an obligation must ship with a matching test change, or a",
    "`Verify-Waive: <id>: <reason>` trailer on one of the branch's commits.",
  );
  out.push("", "| Obligation | Met by a change to |", "| --- | --- |");
  for (const o of OBLIGATIONS) {
    out.push(`| ${code(o.id)}: ${o.title} | ${o.metBy.map(glob).join(", ")} |`);
  }
  out.push("", "### Manual evidence", "");
  out.push("| Evidence | How |", "| --- | --- |");
  for (const e of EVIDENCE) out.push(`| ${code(e.id)}: ${e.title} | ${e.how} |`);
  out.push("", "### E2E map", "");
  out.push("For classes with mapped specs. A file with no entry runs the whole suite.", "");
  out.push("| Source files | Specs |", "| --- | --- |");
  for (const m of E2E_MAP) {
    out.push(`| ${m.paths.map(glob).join(", ")} | ${m.specs.map(code).join(", ")} |`);
  }
  return out.join("\n");
}

export function injectRules(doc: string): string {
  const start = doc.indexOf(START);
  const end = doc.indexOf(END);
  if (start === -1 || end === -1 || end < start) {
    throw new Error("docs/verification.md is missing the verify:rules markers");
  }
  return `${doc.slice(0, start + START.length)}\n\n${renderRules()}\n\n${doc.slice(end)}`;
}
